code:
//! Detect records that hold more than one EXTRACTABLE pure-leaf function — the "each method a single
//! record" ideal, measured (`bsc-graph-detects-multi-method-records`).
//!
//! A blunt function count is useless: 612/694 algorithm records have >1 `fn`, but that count includes
//! `impl` methods, inline `#[cfg(test)]` fns, and — the reason it misleads — CLI dispatchers and cohesive
//! STATEFUL modules that must NOT be split (`epic-command-surfaces-are-nodes` Decision 3: only PURE/LEAF
//! functions are extraction targets; stateful modules stay whole). The signal that matters is how many
//! **extractable pure-leaf** free functions a record carries.
//!
//! The classifier is deliberately CONSERVATIVE — it flags only high-confidence pure leaves, because a
//! false positive makes the worklist noise and the drift gate a nuisance. It under-reports rather than
//! over-reports: a pure function that merely mentions a state/IO token is left off, not wrongly listed.
//! Deterministic and zero-egress: tree-sitter parses locally, the walk is order-stable.

pub(crate) use language_for::language_for;
pub(crate) use is_test_attributed::is_test_attributed;
pub(crate) use fn_name::fn_name;
pub(crate) use module_defined_types::module_defined_types;
pub(crate) use leaf_signature::leaf_signature;
pub(crate) use private_item_names::private_item_names;
pub(crate) use body_references_private::body_references_private;
pub(crate) use cohesion_reason::cohesion_reason;
pub(crate) use is_candidate_record::is_candidate_record;
pub use worklist::worklist;
pub use demoted::demoted;
pub use counts::counts;
pub use drift_against::drift_against;

use serde_json::Value;
use std::collections::BTreeMap;
use tree_sitter::{Node, Parser};

/// Tokens whose presence in a function's TEXT disqualifies it as a pure leaf — shared state, interior
/// mutability, IO, effects, and async. Value types that can be pure parameters (`SystemTime`, `Path`,
/// `Duration`) are deliberately ABSENT; only the impure `::now()`/IO forms are caught, so a pure rule
/// that takes a `SystemTime` in and returns a decision still counts.
///
/// The scan runs over [`impurity_text`], not the raw source: a FUNCTION-LOCAL memo `static` — a
/// `OnceLock` written once through `get_or_init` and only read — is masked out first, because it is
/// invisible to every caller and its type name alone should not disqualify a pure function.
///
/// `Connection` WAS in this list and is not any more — a substring test cannot tell a function that
/// OPENS a database from one that is handed the open handle, and the second shape is exactly what this
/// project wants separated. [`connection_ownership`] makes that distinction against the parser's own
/// parameter span instead.
const IMPURE_MARKERS: &[&str] = &[
    // shared state / interior mutability
    "Mutex", "RwLock", "OnceLock", "OnceCell", "lazy_static", "thread_local", "AtomicUsize",
    "AtomicBool", "AtomicU", "AtomicI", "RefCell", "Cell<", ".lock(", ".borrow(", "static mut ",
    // IO / effects / clocks — impurity, not the value types
    "std::fs", "std::process", "std::env", "File::", "Command", "std::io", "print!", "println!",
    "eprint", "fs::", "process::", "env::", "::now(", "read_to_string", "write_all",
    "spawn", "thread::", "TcpStream", "TcpListener", "Instant", "SystemTime::",
    // async — not a synchronous leaf
    ".await", "async fn", "async move", "tokio::",
];

/// Is this top-level `function_item` a high-confidence extractable pure leaf?
/// Attributes whose macro EMITS SIBLING ITEMS beside the function, so moving the function to another
/// module leaves the generated items behind and the crate stops compiling.
///
/// `#[tauri::command]` generates `__cmd__<name>` and `__tauri_command_name_<name>` in the module that
/// holds the function, and `tauri::generate_handler![module::name]` resolves them THERE. Move the
/// function into a child record and the handler names a module that no longer has them:
///
/// ```text
/// error[E0433]: cannot find `__cmd__record_attestations` in `attest`
/// ```
///
/// MEASURED on the method-leaf backlog: 24 such functions across 12 records were proposed as
/// extractable, and moving them produced 60 errors in `base-studio-code`. The classifier is the right
/// seam for this rather than the verb, because `extract` REUSES it — so the worklist stops proposing
/// them and the verb stops accepting them from one change.
///
/// A named list, not a heuristic: the property is "this macro emits siblings", which cannot be read off
/// the attribute's shape, and a heuristic broad enough to catch it would exclude honest leaves.
const ITEM_GENERATING_ATTRS: [&str; 1] = ["tauri::command"];

/// Does this top-level `function_item` carry a `#[cfg(…)]` attribute?
///
/// A CFG-GATED FUNCTION CANNOT BE EXTRACTED, and this is a stronger rule than the `#[cfg]`-PAIR one it
/// sits beside: a pair breaks because two variants collide on one child id, while a LONE gated function
/// breaks because the re-export the parent gains is UNCONDITIONAL while the item it names is not. On a
/// target where the gate is false the child module is empty, and the parent's `pub use x::x;` resolves
/// to the module rather than the function:
///
/// ```text
/// error[E0432]: no `bash_in_roots` in `platform::shell::bash_in_roots`
///     note: found an item that was configured out
/// error[E0603]: module import `read_stream` is private
/// ```
///
/// MEASURED on this wave, and ONLY by the compiler: `#[cfg(windows)] bash_in_roots` and
/// `#[cfg(windows)] read_stream` were proposed and extracted on Linux, where the gate is false, and
/// `#[cfg(any(windows, target_os = "linux"))] resolve_window` extracted cleanly HERE while being the
/// same latent break on macOS — which is the shape to fear, because this machine compiles neither.
///
/// Refused rather than carried: propagating the gate would mean putting the same `#[cfg]` on the
/// child's `moduleAttrs` AND on the parent's re-export, which is a second conditional-compilation
/// declaration to keep in step with the first. `#[cfg(test)]` needs nothing here — [`is_test_attributed`]
/// already excludes those.
fn is_cfg_gated(node: Node, src: &[u8]) -> bool {
    let mut sib = node.prev_sibling();
    while let Some(sb) = sib {
        match sb.kind() {
            "attribute_item" => {
                let t = sb.utf8_text(src).unwrap_or("").replace(char::is_whitespace, "");
                if t.starts_with("#[cfg(") || t.starts_with("#[cfg_attr(") {
                    return true;
                }
                sib = sb.prev_sibling();
            }
            "line_comment" | "block_comment" => sib = sb.prev_sibling(),
            _ => break,
        }
    }
    false
}

/// Does a top-level `function_item` carry an attribute from [`ITEM_GENERATING_ATTRS`]?
fn generates_sibling_items(node: Node, src: &[u8]) -> bool {
    let mut sib = node.prev_sibling();
    while let Some(s) = sib {
        match s.kind() {
            "attribute_item" => {
                let t = s.utf8_text(src).unwrap_or("");
                if ITEM_GENERATING_ATTRS.iter().any(|a| t.contains(a)) {
                    return true;
                }
                sib = s.prev_sibling();
            }
            // Comments and blank lines sit between an attribute and its item; keep scanning past them,
            // but stop at the previous real item. Same walk as `is_test_attributed`.
            "line_comment" | "block_comment" => sib = s.prev_sibling(),
            _ => break,
        }
    }
    false
}

/// Connection-HANDLE types. A database handle is the one impurity token that says nothing about the
/// function holding it: `fn domains(conn: &Connection) -> Vec<Domain>` owns no state of its own — it is
/// a pure function OF the store, and exactly the shape this project separates. What is impure is OWNING
/// the handle: opening it, resolving its path, or handing one back.
///
/// MEASURED before the split: a blunt `"Connection"` substring in [`IMPURE_MARKERS`] excluded 90
/// functions across 17 records that merely RECEIVE a handle, and four of its hits were not connections
/// at all (`ErrorKind::ConnectionRefused`, `ConnectionSpec`) — which whole-identifier matching fixes on
/// the way past.
const CONNECTION_TYPES: &[&str] = &["Connection"];

/// Does this function OWN a connection rather than merely receive one? `Some(type)` when a
/// [`CONNECTION_TYPES`] identifier is named anywhere OUTSIDE the parameter list — a body calling
/// `Connection::open(…)`, a `-> Result<Connection>` that hands one back, a `let c: Connection` binding.
///
/// The parameter span is read off the tree-sitter `parameters` node rather than sniffed out of the
/// text, so what counts as "in the signature" is the parser's answer and not a guess. Matching is on
/// whole identifiers, so `ConnectionRefused` and `ConnectionSpec` are not connections. Ownership held in
/// a `static` needs nothing here — [`IMPURE_MARKERS`]'s `OnceLock`/`lazy_static`/`static mut` entries
/// already catch it, and they are unchanged.
fn connection_ownership(node: Node, src: &[u8]) -> Option<String> {
    let text = node.utf8_text(src).unwrap_or("");
    let base = node.start_byte();
    let params = node.child_by_field_name("parameters").map(|p| (p.start_byte(), p.end_byte()));
    let owned = |tok: &str, at: usize| -> Option<String> {
        if !CONNECTION_TYPES.contains(&tok) {
            return None;
        }
        // Inside the parameter list it is a handle being RECEIVED; anywhere else it is one being made,
        // named or returned.
        if params.is_some_and(|(s, e)| at >= s && at < e) {
            return None;
        }
        Some(tok.to_string())
    };
    // Whole-identifier scan over char boundaries — a byte walk would slice mid-codepoint on the first
    // non-ASCII character in a string literal.
    let mut start: Option<usize> = None;
    for (i, ch) in text.char_indices() {
        if ch.is_alphanumeric() || ch == '_' {
            if start.is_none() {
                start = Some(i);
            }
            continue;
        }
        if let Some(s) = start.take() {
            if let Some(hit) = owned(&text[s..i], base + s) {
                return Some(hit);
            }
        }
    }
    if let Some(s) = start {
        if let Some(hit) = owned(&text[s..], base + s) {
            return Some(hit);
        }
    }
    None
}

/// Cell types that make a memo. A `OnceLock`/`OnceCell` is written AT MOST ONCE and only ever read
/// back, so a value computed through one is the same value every call.
const MEMO_CELLS: &[&str] = &["OnceLock", "OnceCell"];

/// The only reads that keep a memo referentially transparent: they compute-or-return, and neither can
/// change an already-initialised value. `set`, `take`, `store` and friends are absent DELIBERATELY —
/// a `static` a function writes is shared state whatever its type.
const MEMO_READS: &[&str] = &["get_or_init", "get_or_insert_with"];

/// The byte ranges of this function's FUNCTION-LOCAL memo `static` declarations, or `None` when it holds
/// a `static` that is not a memo (in which case nothing may be excused).
///
/// THE MEMO IDIOM IS REFERENTIALLY TRANSPARENT AND [`IMPURE_MARKERS`] CANNOT SEE IT:
///
/// ```text
/// pub fn declared(text: &str) -> Vec<String> {
///     static RE: OnceLock<regex::Regex> = OnceLock::new();
///     let re = RE.get_or_init(|| regex::Regex::new(r#"…"#).expect("declared"));
///     re.captures_iter(text).map(|c| c[1].to_string()).collect()
/// }
/// ```
///
/// `declared` returns the same value for the same input forever; the cache is invisible to every caller.
/// But the marker scan is a SUBSTRING test over the function's own text, so `OnceLock` disqualifies it.
/// MEASURED across the repo: of 164 `static` declarations only 28 are module-level — 137 are
/// FUNCTION-LOCAL — and roughly 63 of the 88 functions a state marker blocks are this exact shape (31
/// compiled-regex memos, ~32 parsed-seed memos).
///
/// SCOPE IS THE WHOLE RULE, and it is read off the tree — this walks the FUNCTION node's own subtree, so
/// a module-level `static` is not reachable from here and can never be excused, whatever it is called. A
/// substring test cannot make that distinction at all. Three further conditions, each of which is what
/// separates a memo from shared state: the declaration is not `static mut`; its type is a
/// [`MEMO_CELLS`] cell; its value is that cell's `::new()` (a const initialiser, so there is no hidden
/// computation); and EVERY other mention of the name in the function is a [`MEMO_READS`] call. One
/// `SOMETHING.set(…)` and the function is shared state again.
fn memo_static_spans(node: Node, src: &[u8]) -> Option<Vec<(usize, usize)>> {
    let text = node.utf8_text(src).unwrap_or("");
    let base = node.start_byte();
    let mut spans: Vec<(usize, usize)> = Vec::new();
    let mut names: Vec<String> = Vec::new();
    let mut stack = vec![node];
    while let Some(n) = stack.pop() {
        let mut c = n.walk();
        for ch in n.children(&mut c) {
            stack.push(ch);
            if ch.kind() != "static_item" {
                continue;
            }
            // `static mut` is shared mutable state by definition.
            let mut cc = ch.walk();
            if ch.children(&mut cc).any(|k| k.kind() == "mutable_specifier") {
                return None;
            }
            let name = ch.child_by_field_name("name")?.utf8_text(src).ok()?.to_string();
            let ty = ch.child_by_field_name("type")?.utf8_text(src).ok()?;
            let val = ch.child_by_field_name("value")?.utf8_text(src).ok()?;
            // `std::sync::OnceLock<regex::Regex>` -> `OnceLock`
            let head = ty.split('<').next().unwrap_or_default().trim();
            let cell = head.rsplit("::").next().unwrap_or_default();
            if !MEMO_CELLS.contains(&cell) {
                return None;
            }
            // The initialiser is that cell's own `::new()` — a const expression, nothing computed.
            let v: String = val.split_whitespace().collect();
            if !v.ends_with("::new()") || !v.contains(cell) {
                return None;
            }
            spans.push((ch.start_byte(), ch.end_byte()));
            names.push(name);
        }
    }
    // Every mention of a memo's name OUTSIDE its own declaration must be a compute-or-return read.
    for name in &names {
        for at in ident_positions(text, name) {
            let abs = base + at;
            if spans.iter().any(|(s, e)| abs >= *s && abs < *e) {
                continue;
            }
            let after = text[at + name.len()..].trim_start().strip_prefix('.')?;
            if !MEMO_READS.iter().any(|r| after.trim_start().starts_with(r)) {
                return None;
            }
        }
    }
    Some(spans)
}

/// Byte offsets of `name` in `text` as a WHOLE identifier — `RE` inside `CORE` is not a match.
fn ident_positions(text: &str, name: &str) -> Vec<usize> {
    let mut out = Vec::new();
    let mut start: Option<usize> = None;
    for (i, ch) in text.char_indices() {
        if ch.is_alphanumeric() || ch == '_' {
            if start.is_none() {
                start = Some(i);
            }
            continue;
        }
        if let Some(s) = start.take() {
            if &text[s..i] == name {
                out.push(s);
            }
        }
    }
    if let Some(s) = start {
        if &text[s..] == name {
            out.push(s);
        }
    }
    out
}

/// The function's text as [`IMPURE_MARKERS`] should read it: its FUNCTION-LOCAL memo `static`
/// declarations blanked out, so a `OnceLock` that is only ever a cache does not read as shared state.
/// Blanked to the same byte length rather than removed, so the text still lines up with the source.
/// Only the DECLARATION is masked — a memo whose initialiser does IO still trips the scan from its
/// `get_or_init` call site, which is exactly right.
fn impurity_text(node: Node, src: &[u8]) -> String {
    let mut text = node.utf8_text(src).unwrap_or("").to_string();
    let base = node.start_byte();
    let Some(spans) = memo_static_spans(node, src) else { return text };
    for (s, e) in spans {
        let (s, e) = (s - base, e - base);
        text.replace_range(s..e, &" ".repeat(e - s));
    }
    text
}

fn is_extractable_leaf(node: Node, src: &[u8]) -> bool {
    let text = node.utf8_text(src).unwrap_or("");
    if text.is_empty() {
        return false;
    }
    if generates_sibling_items(node, src) {
        return false;
    }
    // A `super::` PATH CHANGES MEANING WHEN THE FUNCTION MOVES. In the flat record `super` is the
    // crate module's parent; in a child record it is the parent RECORD, one level deeper, so
    // `super::studio_ws::…` resolves to nothing:
    //
    //     error[E0433]: cannot find `studio_ws` in `super`
    //
    // Rewriting to `super::super::` would be mechanical but it is a guess about which level was meant,
    // and this verb refuses rather than guesses everywhere else. MEASURED on the method-leaf backlog:
    // 3 functions in 1 record of 39, so the cost of refusing is small and the cost of guessing is a
    // silently wrong path. `use super::*;` — which `extract` itself inserts — is a `use`, not a body
    // path, and is unaffected.
    if text.contains("super::") {
        return false;
    }
    if IMPURE_MARKERS.iter().any(|m| impurity_text(node, src).contains(m)) {
        return false;
    }
    // A store HANDLE is not an impurity of the function that is handed one — see `connection_ownership`.
    if connection_ownership(node, src).is_some() {
        return false;
    }
    // A leaf takes values and returns one. A `&mut` parameter that is not `&mut self` is still a mutation
    // of caller state threaded through — treat it as coupling and leave it out (conservative).
    if let Some(params) = node.child_by_field_name("parameters") {
        let p = params.utf8_text(src).unwrap_or("");
        if p.contains("self") || p.contains("&mut ") {
            return false;
        }
    }
    true
}

/// The extractable pure-leaf function names in one record's `code`, in source order. Empty for a record
/// whose tech has no classifier, or that parses to nothing.
pub fn extractable_leaves(code: &str, tech: &str) -> Vec<String> {
    let Some(lang) = language_for(tech) else {
        return Vec::new();
    };
    let mut parser = Parser::new();
    if parser.set_language(&lang).is_err() {
        return Vec::new();
    }
    let Some(tree) = parser.parse(code, None) else {
        return Vec::new();
    };
    let src = code.as_bytes();
    let root = tree.root_node();
    let mut out = Vec::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        // TOP-LEVEL free functions only. `impl` methods live under `impl_item`, and test fns under
        // `mod_item` — neither is a direct child of `source_file`, so both are excluded by construction.
        if child.kind() != "function_item" {
            continue;
        }
        if is_test_attributed(child, src) || is_cfg_gated(child, src) {
            continue;
        }
        if is_extractable_leaf(child, src) {
            if let Some(name) = fn_name(child, src) {
                out.push(name);
            }
        }
    }
    // A NAME CARRIED BY TWO TOP-LEVEL FUNCTIONS CANNOT BE EXTRACTED — both would become the same child
    // record id, so one would silently overwrite the other. In practice these are `#[cfg]`-gated
    // variants of one function (`signal_number` for two platforms), which are a single module's
    // business and not a decomposition target at all. MEASURED: 2 records on the backlog carry them.
    //
    // Both copies go, not just the duplicate: keeping one would propose extracting half of a cfg pair.
    //
    // THE CENSUS IS OVER EVERY TOP-LEVEL FUNCTION, not over the ones that already passed the leaf
    // filter. A pair whose halves differ in PURITY — `#[cfg(windows)] fn os_alive` shelling out,
    // `#[cfg(not(windows))] fn os_alive` a pure predicate — leaves exactly ONE name in `out`, so a census
    // of `out` cannot see it is a pair and proposes extracting half of one. MEASURED on this backlog:
    // `bsc-fleet--ledger--mod.rs` proposed BOTH `os_alive` and `tree_kill` through that hole, and each is
    // a two-platform pair; taking either would have broken the WINDOWS build only, which nothing on this
    // machine compiles.
    let mut seen: std::collections::BTreeMap<String, usize> = Default::default();
    let mut census = root.walk();
    for child in root.children(&mut census) {
        if child.kind() != "function_item" || is_test_attributed(child, src) {
            continue;
        }
        if let Some(name) = fn_name(child, src) {
            *seen.entry(name).or_default() += 1;
        }
    }
    out.retain(|n| seen.get(n) == Some(&1));
    out
}

/// The function names a record declares as `#[tauri::command]` in its `tauriCommands` FACET.
///
/// `a-tauri-command-is-a-record-facet` moved the attribute out of the body: `render` re-attaches it and
/// builds `generate_handler!` from this one declaration. That makes [`ITEM_GENERATING_ATTRS`] — a scan of
/// the body TEXT — blind to exactly the functions it exists to protect, because the text no longer
/// carries the attribute. Both the worklist and the verb read the facet instead, so a command is refused
/// wherever it is named.
pub(crate) fn tauri_command_names(rec: &Value) -> std::collections::HashSet<String> {
    rec.get("tauriCommands")
        .and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter_map(|c| c.get("name").and_then(Value::as_str).map(str::to_string))
                .collect()
        })
        .unwrap_or_default()
}

/// One record's extractable-leaf finding.
#[derive(Debug, Clone)]
pub struct RecordLeaves {
    pub id: String,
    pub names: Vec<String>,
}

/// The decomposition TRANSFORM behind `bsc graph extract`. Kept in an INNER module so its helpers
/// are not top-level free functions of `methods` (the drift classifier counts only module-scope
/// leaves), while `use super::*` still reaches this module's private detection helpers.
pub use extract_transform::{plan_extraction, ExtractionPlan};

mod extract_transform {
use super::*;

// ===================================================================================================
// The decomposition TRANSFORM — `bsc graph extract`. Automates the per-method decomposition template a
// worker runs by hand today (requests #249/#250): a flat record holding several pure-leaf free
// functions becomes a `--mod.rs` dir-module parent that re-exports one child record per function.
//
// PURE. `plan_extraction` reads the flat record and returns records; it touches no store and no
// filesystem. The CLI seam applies the plan to the committed repo store, so the transform is provable
// on a fixture the same way the detection above is. It REUSES that detection — `is_extractable_leaf`,
// `body_references_private`, `private_item_names` — so the verb refuses exactly the functions the
// worklist would never have proposed, and names WHY.
// ===================================================================================================

/// The record id that materializes a module at repo-relative `src`, mirroring
/// `graph_materialize::plan::expected_id` (a dev-dependency — unreachable from this runtime code, so the
/// one rule both must agree on is restated here and pinned by a test). Kebab each segment after `src/`,
/// join with `--`, prepend the kebabed crate dir. Rust module names are snake_case, so kebabing is a
/// `_`→`-` swap. An id whose underscores were NOT hyphenated SILENTLY fails to materialize (the emitter
/// compares against exactly this), so every id the plan mints is derived HERE from the src it will land
/// at, never spelled by hand.
fn record_id_for(src: &str) -> Option<String> {
    let stem = src.strip_suffix(".rs")?;
    let idx = stem.find("/src/")?;
    let crate_dir = stem[..idx].rsplit('/').next().filter(|s| !s.is_empty())?;
    let rest = &stem[idx + "/src/".len()..];
    let mut segs = vec![crate_dir.replace('_', "-")];
    segs.extend(rest.split('/').filter(|s| !s.is_empty()).map(|s| s.replace('_', "-")));
    Some(format!("{}.rs", segs.join("--")))
}

/// The visibility modifier VERBATIM on a top-level item, canonically spaced (`pub(crate)`), or
/// `"private"` when the item declares none.
fn item_vis(node: Node, src: &[u8]) -> String {
    let mut c = node.walk();
    for ch in node.children(&mut c) {
        if ch.kind() == "visibility_modifier" {
            return ch.utf8_text(src).unwrap_or("pub").split_whitespace().collect::<String>();
        }
    }
    "private".to_string()
}

/// Byte offset where an item's leading doc-comment / attribute block starts — so a function extracts
/// WITH its `///` docs and `#[…]` attributes, not stripped of them. Walks contiguous `attribute_item`
/// and comment siblings immediately above the item, stopping at the previous real item or a blank-line
/// gap (a comment separated from the fn by a blank line belongs to whatever is above it, not to the fn).
fn item_lead_start(node: Node, src: &[u8]) -> usize {
    let mut start = node.start_byte();
    let mut sib = node.prev_sibling();
    while let Some(s) = sib {
        if !matches!(s.kind(), "attribute_item" | "line_comment" | "block_comment") {
            break;
        }
        // A blank line between this sibling and what currently begins the block detaches it.
        let between = std::str::from_utf8(&src[s.end_byte()..start]).unwrap_or("");
        if between.matches('\n').count() > 1 {
            break;
        }
        start = s.start_byte();
        sib = s.prev_sibling();
    }
    start
}

/// Names brought into module scope by top-level `use` declarations — the last path segment of a simple
/// `use a::b::C`, and every leaf of a `use a::{B, c::D}` list. Crude by design: a child that references
/// any of them needs `use super::*`, and over-reporting only adds a harmless glob import (an unused
/// `use super::*` is not linted).
fn imported_names(root: Node, src: &[u8]) -> std::collections::HashSet<String> {
    let mut names = std::collections::HashSet::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if child.kind() != "use_declaration" {
            continue;
        }
        // Every identifier / type_identifier under the use tree; the final segments are what land in
        // scope, and incidental path roots do no harm in a set used only for a membership test.
        collect_idents(child, src, &mut names);
    }
    names
}

/// Every `identifier` / `type_identifier` leaf under `node` — used to gather what a `use` brings in.
fn collect_idents(node: Node, src: &[u8], into: &mut std::collections::HashSet<String>) {
    if matches!(node.kind(), "identifier" | "type_identifier") {
        into.insert(node.utf8_text(src).unwrap_or_default().to_string());
    }
    let mut c = node.walk();
    for ch in node.children(&mut c) {
        collect_idents(ch, src, into);
    }
}

/// Does the module carry a WILDCARD `use` (`use crate::prelude::*;`)?
///
/// [`imported_names`] enumerates what a `use` brings into scope, and a glob defeats enumeration
/// completely: `use crate::prelude::*` binds names this transform cannot see, so a child that reaches
/// one of them looks self-contained and is emitted WITHOUT `use super::*`:
///
/// ```text
/// error[E0425]: cannot find function `bsc_base_dir` in this scope
/// ```
///
/// MEASURED on this wave: `mcp_install_dir` and `cache_dir`, both reaching `bsc_base_dir` through their
/// parent's prelude glob. When the parent has one, every child gets `use super::*` — a glob is the only
/// honest answer to a glob, and the direction of the error decides it: a needless import is a warning
/// that [`ExtractionPlan`]'s `#[allow(unused_imports)]` covers, a missing one does not compile.
fn has_wildcard_use(root: Node, src: &[u8]) -> bool {
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if child.kind() != "use_declaration" {
            continue;
        }
        let mut stack = vec![child];
        while let Some(n) = stack.pop() {
            if n.kind() == "use_wildcard" {
                return true;
            }
            let mut c = n.walk();
            for ch in n.children(&mut c) {
                stack.push(ch);
            }
        }
        // A parse the grammar did not shape as `use_wildcard` still reads as one in the text.
        if child.utf8_text(src).unwrap_or("").contains("::*") {
            return true;
        }
    }
    false
}

/// Top-level item names of any visibility — fn / struct / enum / const / static / type / union / trait.
/// A child that names one of these needs `use super::*` to reach it (a glob re-exports the pub ones;
/// referencing a PRIVATE one is refused earlier).
fn top_level_item_names(root: Node, src: &[u8]) -> std::collections::HashSet<String> {
    let mut names = std::collections::HashSet::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if !matches!(
            child.kind(),
            "function_item" | "struct_item" | "enum_item" | "const_item" | "static_item"
                | "type_item" | "union_item" | "trait_item"
        ) {
            continue;
        }
        if let Some(nm) = child.child_by_field_name("name") {
            names.insert(nm.utf8_text(src).unwrap_or_default().to_string());
        }
    }
    names
}

/// The function's text with STRING and CHARACTER literals — and inner comments — BLANKED, so a name
/// that occurs only inside a literal is not read as a reference to a parent item.
///
/// A literal containing `{` is kept WHOLE. `format!("{roster_path}")` captures an identifier inline, so
/// blanking that would lose a REAL reference and drop a `use super::*` the child needs — a compile
/// error, where the false positive it fixes is only a warning. The asymmetry decides the rule: blank
/// only what cannot possibly hold a reference.
///
/// MEASURED on this wave: `bsc-sound--release--artifact-name.rs` is `fn artifact_name(_kind: &str) ->
/// &'static str { "kit.json" }`, whose literal tokenizes to `kit`/`json` and matched a parent-scope
/// name — so the child was handed a `use super::*` it does not use. This workspace gates on
/// `clippy --all-targets -- -D warnings`, so "a harmless extra glob import" is a RED GATE. The claim in
/// [`imported_names`] that an unused glob is not linted is simply false, and this is the evidence.
///
/// Blanking preserves BYTE LENGTH (each blanked range becomes spaces), so nothing downstream that works
/// in offsets is disturbed by using it.
fn reference_text(node: Node, src: &[u8]) -> String {
    let base = node.start_byte();
    let mut text = node.utf8_text(src).unwrap_or("").to_string();
    let mut blanks: Vec<(usize, usize)> = Vec::new();
    let mut stack = vec![node];
    while let Some(n) = stack.pop() {
        let mut c = n.walk();
        for ch in n.children(&mut c) {
            stack.push(ch);
        }
        if !matches!(
            n.kind(),
            "string_literal" | "raw_string_literal" | "char_literal" | "line_comment" | "block_comment"
        ) {
            continue;
        }
        let t = n.utf8_text(src).unwrap_or("");
        if t.contains('{') {
            continue;
        }
        blanks.push((n.start_byte() - base, n.end_byte() - base));
    }
    blanks.sort_by_key(|a| std::cmp::Reverse(a.0));
    for (s, e) in blanks {
        if e <= text.len() && text.is_char_boundary(s) && text.is_char_boundary(e) {
            text.replace_range(s..e, &" ".repeat(e - s));
        }
    }
    text
}

/// Does `body` reference `name` as a whole-word identifier, other than `own`? Same tokenizer as
/// [`body_references_private`], so `add` inside `address` does not match.
fn references_name(body: &str, own: &str, name: &str) -> bool {
    body.split(|c: char| !c.is_alphanumeric() && c != '_').any(|tok| tok != own && tok == name)
}

/// Byte offset just past the module's leading PREAMBLE — its `//!` header and any inner attributes —
/// or 0 when the module opens with neither. The re-exports are inserted here so they sit after the
/// preamble and before the module body.
///
/// INNER ATTRIBUTES ARE PART OF IT, and leaving them out produced code that does not compile. An
/// inner attribute must precede every item in its module, so inserting `pub use` above a `#![allow(…)]`
/// moves the attribute after an item:
///
/// ```text
/// error: an inner attribute is not permitted in this context
/// ```
///
/// MEASURED on the extraction backlog: 1 of 39 records (`bsc-github--repo-credentials.rs`) carried one,
/// and it broke the workspace build. Blank lines and ordinary `//` comments are tolerated INSIDE the
/// run, because an attribute is routinely preceded by a comment explaining it — but they do not
/// themselves extend the preamble, since a `//` comment directly above an item belongs to that item and
/// the re-exports must not be wedged between the two.
fn header_end_byte(code: &str) -> usize {
    let mut off = 0usize;
    let mut header_end = 0usize;
    for line in code.split_inclusive('\n') {
        let t = line.trim_start();
        if t.starts_with("//!") || t.starts_with("#![") {
            off += line.len();
            header_end = off;
        } else if t.trim().is_empty() || t.starts_with("//") {
            // Tolerated INSIDE the run but not part of it: only a `//!` or `#![` line moves the end,
            // so a comment attached to the first real item stays attached to it.
            off += line.len();
        } else {
            break;
        }
    }
    header_end
}

/// Collapse 3+ consecutive newlines to 2 and guarantee exactly one trailing newline — tidies the blank
/// runs left where a moved function used to sit, so the parent reads as if hand-decomposed.
fn tidy(mut s: String) -> String {
    while s.contains("\n\n\n") {
        s = s.replace("\n\n\n", "\n\n");
    }
    let trimmed = s.trim_end().to_string();
    format!("{trimmed}\n")
}

/// The refusal reason for extracting `node` (a named top-level free fn), or `None` if it is a clean pure
/// leaf that also does not reach a private parent item that stays behind. Reuses the same predicates the
/// worklist classifier uses, so `extract` refuses exactly what the worklist would never have proposed —
/// and says WHY, so the human picks a different function rather than getting a guess.
fn extraction_refusal(
    node: Node,
    src: &[u8],
    private_targets: &std::collections::HashSet<String>,
) -> Option<String> {
    let text = node.utf8_text(src).unwrap_or("");
    if text.is_empty() {
        return Some("its body could not be read".to_string());
    }
    if is_cfg_gated(node, src) {
        return Some(
            "it is `#[cfg]`-gated — the re-export the parent gains is UNCONDITIONAL while the function \
             is not, so on a target where the gate is false the child module is empty and the parent \
             re-exports a name that is not there. Leave it in the module"
                .to_string(),
        );
    }
    let scan = impurity_text(node, src);
    if let Some(m) = IMPURE_MARKERS.iter().find(|m| scan.contains(**m)) {
        return Some(format!(
            "it is not a pure leaf — its body uses `{m}` (shared state / IO / effect / async). Only pure \
             free functions extract cleanly; a stateful or effectful one stays with the module"
        ));
    }
    if let Some(t) = connection_ownership(node, src) {
        return Some(format!(
            "it OWNS a connection — `{t}` is named outside its parameter list, so it opens, binds or \
             returns the handle rather than being handed one. A function that TAKES a `&{t}` and queries \
             it extracts cleanly; one that opens it stays with the module"
        ));
    }
    if let Some(params) = node.child_by_field_name("parameters") {
        let p = params.utf8_text(src).unwrap_or("");
        if p.contains("self") {
            return Some("it is a method (takes `self`), not a free function".to_string());
        }
        if p.contains("&mut ") {
            return Some(
                "it takes a `&mut` parameter — it threads caller state through, so it is not a pure leaf"
                    .to_string(),
            );
        }
    }
    let name = fn_name(node, src).unwrap_or_default();
    if body_references_private(text, &name, private_targets) {
        return Some(format!(
            "it references a PRIVATE item of the module that would stay behind — a glob re-export reaches \
             only the pub items, so `{name}` cannot travel on its own. Extract that helper in the same \
             call, or leave `{name}` in the module"
        ));
    }
    None
}

/// A decomposition plan: the rewritten `--mod.rs` parent record and one child record per extracted
/// function. The CLI applies it to the committed repo store; nothing here reads or writes.
#[derive(Debug, Clone)]
pub struct ExtractionPlan {
    /// The record id being decomposed. A FLAT record is removed from the store as the plan lands; an
    /// [`Self::in_place`] parent shares this id with [`Self::parent`], so the store seam's
    /// remove-then-insert is an UPDATE rather than a replacement, with no separate code path.
    pub flat_id: String,
    /// The rewritten dir-module parent (`…--mod.rs`).
    pub parent: Value,
    /// One child record per extracted function, in the order named.
    pub children: Vec<Value>,
    /// True when the record was ALREADY a `--mod.rs` parent: the children land as SIBLINGS in the
    /// directory it owns and its id survives, so its drift-baseline entry is re-counted, not dropped.
    pub in_place: bool,
}

/// Plan the decomposition of one `record` into a `--mod.rs` dir-module, extracting each function in
/// `fn_names` into its own child record. PURE — see [`ExtractionPlan`].
///
/// Takes BOTH geometries. A FLAT record becomes a new dir-module parent with the children beneath it. A
/// record that is ALREADY a `--mod.rs` parent is decomposed FURTHER, in place: the children land as
/// siblings in the directory it owns, its existing children stay on `composes`, and its id and src do not
/// move (`bsc request` #260). A CRATE ROOT is refused in either direction.
///
/// Refuses (never guesses) when a named function is not a pure free-fn leaf, or reaches a private parent
/// item that would stay behind, naming WHY so the caller picks differently. Scope is the COMMON case —
/// pure free-fn → child, the exact shape the by-hand decompose forks produced. It does not attempt to
/// split a stateful module, move an `impl` method, or reason about macro-generated items.
pub fn plan_extraction(record: &Value, fn_names: &[String]) -> Result<ExtractionPlan, String> {
    let flat_id = record.get("id").and_then(Value::as_str).ok_or("record has no `id`")?.to_string();
    let tech = record.get("tech").and_then(Value::as_str).unwrap_or("");
    if tech != "rust" {
        return Err(format!(
            "extract supports Rust only (record `{flat_id}` is tech `{tech}`) — the decomposition template \
             is the Rust crate-module one"
        ));
    }
    let code = record.get("code").and_then(Value::as_str).ok_or("record has no `code`")?;
    let src = record.get("src").and_then(Value::as_str).ok_or_else(|| {
        format!("record `{flat_id}` has no `src` — a dir-module's child paths derive from it")
    })?;
    // TWO GEOMETRIES, and the record's own id picks between them (`bsc request` #260). They differ in
    // exactly one variable — `dir`, the directory the children land in — and everything else falls out
    // of it, because the parent's id and src are DERIVED from `dir` rather than spelled.
    //
    // FLAT -> DIR: `dir` is `src` minus `.rs`, the children land beneath it, and the flat record is
    // REPLACED by a newly minted `--mod.rs` parent that re-exports them.
    //
    // DIR -> SAME DIR (`in_place`): the record is ALREADY the `--mod.rs` parent of `dir`, so the children
    // land as its SIBLINGS in the directory it already owns; the derivation of the parent id/src is then
    // the IDENTITY, so the record is updated in place — same id, same src, its existing children kept on
    // `composes` — and the CLI seam re-counts its `method-leaf-baseline.json` entry rather than dropping
    // it, because a partial extraction usually leaves leaves behind.
    //
    // A CRATE ROOT is a THIRD shape and is refused PERMANENTLY — it is not a module and can never become
    // a dir-module. That refusal was never waiting on a capability, and #260 did not lift it.
    let in_place = flat_id.ends_with("--mod.rs");
    // A CRATE ROOT IS NOT A MODULE, and this refusal is not theoretical — it was reported `ok` twice
    // while breaking the build. `graph_materialize` finds a crate's root unit by exactly
    // (`crates/x/src/lib.rs`, `x--lib.rs`) — `Plan::select_root` — and materializes its body at the top
    // of the generated `crate.rs`. This transform would mint a parent at `crates/x/src/lib/mod.rs` and
    // DELETE the `x--lib.rs` record, so the crate builds with an EMPTY root and every item it defined
    // vanishes. MEASURED: `bsc-graph-store--lib.rs` rewritten this way took every `crate::` path with
    // it, and `bsc graph extract bsc--main.rs --fn members_of --into-mod` printed `{"ok":true}` and
    // produced six `E0433 cannot find module or crate` errors, because `main.rs` is a binary ENTRY POINT
    // — moving it to `src/main/mod.rs` leaves the binary with no entry and its siblings unresolvable.
    // The worklist DOES propose crate roots — every one of the 15 records it carried before this change
    // was a `--lib.rs` — so the refusal has to live here, in the verb.
    if flat_id.ends_with("--lib.rs") || flat_id.ends_with("--main.rs") {
        return Err(format!(
            "`{flat_id}` is a CRATE ROOT, not a module — `graph-materialize` finds the crate's root unit \
             by that exact id, and a `main.rs` is a binary's entry point besides. Moving it into a \
             dir-module leaves the crate with an empty root and its siblings unresolvable. Move the \
             functions into a declared child module first, then extract there"
        ));
    }
    // The id must be the one its own `src` materializes to, or the children this plan mints (derived the
    // same way) would silently fail to materialize. Catch a mismatched store up front.
    match record_id_for(src) {
        Some(expected) if expected == flat_id => {}
        Some(expected) => {
            return Err(format!(
                "record `{flat_id}` has src `{src}`, which materializes id `{expected}` — the record is \
                 mis-keyed, so a decomposition derived from its src would not compile"
            ));
        }
        None => return Err(format!("cannot derive a module id from src `{src}` (expected `…/src/…​.rs`)")),
    }
    if fn_names.is_empty() {
        return Err("name at least one function to extract with --fn <name>[,<name>…]".to_string());
    }
    // A `#[tauri::command]` DECLARED AS A FACET. The attribute is not in the body any more
    // (`a-tauri-command-is-a-record-facet`), so the [`ITEM_GENERATING_ATTRS`] text scan cannot see it and
    // the function reads as an ordinary pure leaf. Moving one produces a parent whose `tauriCommands`
    // entry names a function it no longer holds, and `graph-materialize` refuses to build:
    //
    // ```text
    // record `src-tauri--extensions--mcp--mod.rs` declares `mcp_status` as a #[tauri::command] but its
    // body has no `fn mcp_status` — the facet names a function that is not there.
    // ```
    //
    // MEASURED: that record carries four entries, two of which a wave extracted before this refusal
    // existed. Refused rather than migrated — moving the facet to the child would also move the handler
    // path the frontend calls, which is a decision about the app's IPC surface and not a decomposition.
    let commands = tauri_command_names(record);
    if let Some(c) = fn_names.iter().find(|n| commands.contains(n.as_str())) {
        return Err(format!(
            "cannot extract `{c}`: `{flat_id}` declares it as a `#[tauri::command]` in its \
             `tauriCommands` facet. The attribute is re-attached at materialization, so moving the \
             function leaves the facet naming one the module no longer has and the build refuses it. \
             Extract the other leaves"
        ));
    }
    // MODULE INCEPTION. A leaf whose name matches the record's own module produces `mod x` inside
    // `mod x`, which clippy denies workspace-wide:
    //
    //     error: module has the same name as its containing module
    //
    // MEASURED on the method-leaf backlog: `bsc-ui--validate-value.rs::validate_value` and
    // `logs--pending.rs::pending`, 2 of 111 leaves. Refused rather than renamed, because the child
    // record's id IS its module path and a name the caller did not ask for is a guess — the same
    // stance this verb takes on every other shape it will not decompose.
    // `crates/x/src/foo/mod.rs` IS module `foo`, so a PARENT's own name is the segment BEFORE
    // `--mod.rs`. Reading the last segment for it would compare every leaf against the literal `mod`,
    // and a genuine `foo/foo.rs` inception would sail straight through into a clippy denial.
    let own_module = if in_place {
        flat_id.trim_end_matches(".rs").rsplit("--").nth(1).unwrap_or_default()
    } else {
        flat_id.rsplit("--").next().unwrap_or_default().trim_end_matches(".rs")
    };
    if let Some(clash) = fn_names.iter().find(|n| n.replace('_', "-") == own_module) {
        return Err(format!(
            "`{clash}` has the same name as its module (`{own_module}`), so extracting it would produce              `mod {clash}` inside `mod {own_module}` — clippy's `module_inception`, denied workspace-wide.              Extract the other leaves, or rename the function first."
        ));
    }

    let lang = language_for(tech).ok_or_else(|| format!("no classifier for tech `{tech}`"))?;
    let mut parser = Parser::new();
    parser.set_language(&lang).map_err(|e| format!("tree-sitter: {e}"))?;
    let tree = parser.parse(code, None).ok_or("could not parse the record's code")?;
    let bytes = code.as_bytes();
    let root = tree.root_node();

    let want: std::collections::HashSet<&str> = fn_names.iter().map(String::as_str).collect();
    // Private parent items that are NOT themselves being extracted — the ones that stay behind. A leaf
    // reaching one of these is refused (same rule as the worklist's cohesion check).
    let private_targets: std::collections::HashSet<String> =
        private_item_names(root, bytes).into_iter().filter(|n| !want.contains(n.as_str())).collect();
    // What a child might need `use super::*` to reach: parent items (any vis) and use-imports, plus the
    // OTHER extracted names, which are re-exported at the parent.
    let mut parent_scope = top_level_item_names(root, bytes);
    parent_scope.extend(imported_names(root, bytes));
    parent_scope.extend(fn_names.iter().cloned());
    // A glob in the parent makes `parent_scope` an UNDER-estimate of what is reachable, so every child
    // takes `use super::*` — see [`has_wildcard_use`].
    let parent_globs = has_wildcard_use(root, bytes);

    // Locate each named top-level free function, in the order requested, refusing with a reason.
    struct Located<'a> {
        name: String,
        node: Node<'a>,
    }
    let mut located: Vec<Located> = Vec::new();
    for want_name in fn_names {
        // COLLECT EVERY MATCH, never the first. Two top-level functions sharing a name are `#[cfg]`-gated
        // variants of one function; taking the first moves ONE variant into a child and leaves the other
        // in the parent, which then re-exports a name it also defines — a break on whichever platform
        // keeps the variant that stayed. The classifier drops these too, but this verb accepts a name
        // from a human as readily as from the worklist, and the two must refuse the same thing.
        let mut hits: Vec<Node> = Vec::new();
        let mut cursor = root.walk();
        for child in root.children(&mut cursor) {
            if child.kind() != "function_item" {
                continue;
            }
            if fn_name(child, bytes).as_deref() == Some(want_name.as_str()) {
                hits.push(child);
            }
        }
        if hits.len() > 1 {
            return Err(format!(
                "cannot extract `{want_name}`: {n} top-level functions in `{flat_id}` carry that name, so \
                 they are `#[cfg]`-gated variants of one function. Extracting moves one variant and leaves \
                 the other behind in a module that then re-exports a name it also defines — a build break \
                 on whichever platform keeps the one that stayed",
                n = hits.len()
            ));
        }
        let node = hits.into_iter().next().ok_or_else(|| {
            format!("no top-level free function `{want_name}` in `{flat_id}` (it is not a `fn` at module scope)")
        })?;
        if let Some(reason) = extraction_refusal(node, bytes, &private_targets) {
            return Err(format!("cannot extract `{want_name}`: {reason}"));
        }
        located.push(Located { name: want_name.clone(), node });
    }

    // "crates/<crate>/src/<X>" — minted from `src` for a flat record, and for a parent the directory it
    // ALREADY owns, which is `src` minus `/mod.rs`. Stripping only `.rs` there would name a
    // `…/<X>/mod/` directory that does not exist and mint grandchildren instead of siblings.
    let dir = if in_place {
        src.strip_suffix("/mod.rs").unwrap_or(src)
    } else {
        src.strip_suffix(".rs").unwrap_or(src)
    };
    let feature = record.get("feature").cloned();

    // ---- children ----
    let mut children = Vec::new();
    for l in &located {
        let vis = item_vis(l.node, bytes);
        let lead = item_lead_start(l.node, bytes);
        let fn_start = l.node.start_byte();
        let end = l.node.end_byte();
        let lead_text = &code[lead..fn_start];
        let fn_text = &code[fn_start..end];
        // A private fn becomes `pub(crate) fn` so the parent can re-export it; a declared vis is kept.
        let bumped = if vis == "private" {
            format!("pub(crate) {fn_text}")
        } else {
            fn_text.to_string()
        };
        // Against the LITERAL-BLANKED text: an identifier that occurs only inside `"kit.json"` is not a
        // reference to the parent's `kit`, and the `use super::*` it would earn is an unused import
        // under `-D warnings`.
        let ref_text = reference_text(l.node, bytes);
        let needs_super =
            parent_globs || parent_scope.iter().any(|n| references_name(&ref_text, &l.name, n));
        let mut body = String::new();
        if needs_super {
            body.push_str("use super::*;\n\n");
        }
        body.push_str(lead_text);
        body.push_str(&bumped);
        let body = tidy(body);

        let child_src = format!("{dir}/{}.rs", l.name);
        let child_id = record_id_for(&child_src)
            .ok_or_else(|| format!("cannot derive a child id for `{}`", l.name))?;
        // child -> child: this fn calls another extracted fn (now a sibling module).
        let composes: Vec<Value> = located
            .iter()
            .filter(|o| o.name != l.name && references_name(&ref_text, &l.name, &o.name))
            .filter_map(|o| record_id_for(&format!("{dir}/{}.rs", o.name)).map(Value::String))
            .collect();

        let mut child = serde_json::json!({
            "id": child_id,
            "tech": "rust",
            "role": "algorithm",
            "name": l.name,
            "src": child_src,
            "folder": dir,
            "moduleVis": "private",
            "composes": composes,
            "code": body,
        });
        // A CHILD THAT TAKES `use super::*` ALLOWS AN UNUSED ONE, and that attribute is what makes
        // [`imported_names`]'s "over-reporting is harmless" claim TRUE rather than merely hoped for.
        // The claim was false: this workspace gates on `clippy --all-targets -- -D warnings`, so a glob
        // the child does not happen to need is a RED GATE. Deciding it exactly needs name resolution
        // the transform does not have — a parent glob is unenumerable by construction — so the choice
        // is between a suppressed warning in a generated module and a mechanical edit that cannot land.
        if needs_super {
            child["moduleAttrs"] = serde_json::json!(["#[allow(unused_imports)]"]);
        }
        if let Some(f) = &feature {
            child["feature"] = f.clone();
        }
        children.push(child);
    }

    // ---- parent ----
    // Strip each moved fn (docs/attrs..end) from the code, largest offset first so earlier ranges hold.
    let mut ranges: Vec<(usize, usize)> =
        located.iter().map(|l| (item_lead_start(l.node, bytes), l.node.end_byte())).collect();
    ranges.sort_by_key(|a| std::cmp::Reverse(a.0));
    let mut stripped = code.to_string();
    for (s, e) in ranges {
        stripped.replace_range(s..e, "");
    }
    // Re-export block, in the order named — `pub use` for a pub fn, else `pub(crate) use`.
    let reexports: String = located
        .iter()
        .map(|l| {
            let vis = item_vis(l.node, bytes);
            let use_vis = if vis == "pub" { "pub" } else { "pub(crate)" };
            format!("{use_vis} use {name}::{name};", name = l.name)
        })
        .collect::<Vec<_>>()
        .join("\n");
    let h = header_end_byte(&stripped);
    let parent_code = if h == 0 {
        format!("{reexports}\n\n{stripped}")
    } else {
        format!("{}\n{reexports}\n{}", &stripped[..h], &stripped[h..])
    };
    let parent_code = tidy(parent_code);

    // `#[allow(unused_imports)]` UNCONDITIONALLY once a function leaves, which is wider than the
    // CONSUMER-ONLY re-export case it started as. Two ways an extraction orphans an import in the
    // parent, and the second is not about re-exports at all:
    //
    //   1. the re-export is consumer-only — the fn is not referenced in the retained body, so the
    //      `pub use` itself trips `unused_imports`;
    //   2. the MOVED FUNCTION was the only user of one of the parent's `use` declarations, which now
    //      imports a name nothing reads. MEASURED: `src-tauri--project--graph-layout--mod.rs` kept
    //      `use crate::prelude::*;` after `cache_dir` and `header` left — an unused import, and this
    //      workspace gates on `-D warnings`.
    //
    // Pruning case 2 exactly needs name resolution (a `use` can be load-bearing without its name ever
    // appearing — a trait in scope for a method call), and a glob cannot be pruned at all. The
    // attribute is what the transform already reached for; it is now applied for the whole reason.
    let consumer_only = true;

    let parent_src = format!("{dir}/mod.rs");
    let parent_id = record_id_for(&parent_src)
        .ok_or_else(|| format!("cannot derive a parent id for `{parent_src}`"))?;
    let child_ids: Vec<String> =
        children.iter().filter_map(|c| c.get("id").and_then(Value::as_str).map(str::to_string)).collect();
    // parent -> each child, and keep any original composes that did not point at a child.
    let mut composes: Vec<Value> = child_ids.iter().cloned().map(Value::String).collect();
    if let Some(orig) = record.get("composes").and_then(Value::as_array) {
        for c in orig {
            if let Some(s) = c.as_str() {
                if !child_ids.iter().any(|id| id == s) {
                    composes.push(Value::String(s.to_string()));
                }
            }
        }
    }

    // Carry the flat record's fields (summary, tests, domain, moduleVis, …) and override what the split
    // changes. Write-bookkeeping is stripped by the CLI on its way into the committed store.
    let mut parent = record.clone();
    parent["id"] = Value::String(parent_id);
    parent["src"] = Value::String(parent_src);
    parent["folder"] = Value::String(dir.to_string());
    parent["composes"] = Value::Array(composes);
    parent["code"] = Value::String(parent_code);
    if consumer_only {
        let mut attrs = parent
            .get("moduleAttrs")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let allow = Value::String("#[allow(unused_imports)]".to_string());
        if !attrs.contains(&allow) {
            attrs.push(allow);
        }
        parent["moduleAttrs"] = Value::Array(attrs);
    }

    Ok(ExtractionPlan { flat_id, parent, children, in_place })
}

#[cfg(test)]
mod tests {
use super::*;

    // A flat record shaped like the real by-hand decompose targets: a `//!` header, a `use`, a retained
    // struct + impl + const + private helper, and a mix of pure leaves — one self-contained, one that
    // needs the parent's import, one calling a sibling leaf, and two that MUST be refused.
    fn fixture() -> Value {
        let code = "\
//! Widget helpers.
//!
//! Second header line.

use serde_json::Value;

const LIMIT: usize = 4;

pub struct Widget {
    pub n: usize,
}

impl Widget {
    pub fn bump(&mut self) {
        self.n += 1;
    }
}

fn secret(n: usize) -> usize {
    n * LIMIT
}

/// Double a number.
pub fn double(x: usize) -> usize { x + x }

/// Name of a value — needs the parent's `Value` import.
pub(crate) fn name_of(v: &Value) -> String {
    v.get(\"n\").and_then(Value::as_str).unwrap_or(\"\").to_string()
}

/// Triple via double.
pub fn triple(x: usize) -> usize { double(x) + x }

/// Uses the private const-backed helper — must be refused.
pub fn scaled(n: usize) -> usize { secret(n) + 1 }

pub fn io_write(p: &str) {
    std::fs::write(p, \"x\").ok();
}
";
        serde_json::json!({
            "id": "bsc-demo--widget.rs",
            "tech": "rust",
            "role": "algorithm",
            "name": "widget",
            "src": "crates/bsc-demo/src/widget.rs",
            "feature": "core",
            "composes": ["bsc-demo--other.rs"],
        })
        .as_object()
        .cloned()
        .map(|mut m| {
            m.insert("code".to_string(), Value::String(code.to_string()));
            Value::Object(m)
        })
        .unwrap()
    }

    fn child<'a>(plan: &'a ExtractionPlan, id: &str) -> &'a Value {
        plan.children
            .iter()
            .find(|c| c.get("id").and_then(Value::as_str) == Some(id))
            .unwrap_or_else(|| panic!("no child `{id}` in plan (have {:?})",
                plan.children.iter().filter_map(|c| c.get("id").and_then(Value::as_str)).collect::<Vec<_>>()))
    }

    #[test]
    fn record_id_hyphenates_the_functions_underscores() {
        assert_eq!(record_id_for("crates/bsc-demo/src/widget/name_of.rs").as_deref(),
                   Some("bsc-demo--widget--name-of.rs"));
        assert_eq!(record_id_for("crates/bsc-fin/src/balance.rs").as_deref(),
                   Some("bsc-fin--balance.rs"));
        assert_eq!(record_id_for("crates/bsc-demo/src/widget/mod.rs").as_deref(),
                   Some("bsc-demo--widget--mod.rs"));
    }

    #[test]
    fn extract_mints_hyphenated_child_ids_the_parent_reexports_and_removes_the_flat_record() {
        let plan = plan_extraction(
            &fixture(),
            &["double".into(), "name_of".into(), "triple".into()],
        )
        .expect("clean pure leaves extract");

        assert_eq!(plan.flat_id, "bsc-demo--widget.rs");

        // hyphenated child ids
        let ids: Vec<&str> =
            plan.children.iter().filter_map(|c| c.get("id").and_then(Value::as_str)).collect();
        assert_eq!(ids, vec![
            "bsc-demo--widget--double.rs",
            "bsc-demo--widget--name-of.rs",
            "bsc-demo--widget--triple.rs",
        ]);

        // src / name keep underscores; module is private; feature carried
        let nm = child(&plan, "bsc-demo--widget--name-of.rs");
        assert_eq!(nm.get("name").and_then(Value::as_str), Some("name_of"));
        assert_eq!(nm.get("src").and_then(Value::as_str), Some("crates/bsc-demo/src/widget/name_of.rs"));
        assert_eq!(nm.get("moduleVis").and_then(Value::as_str), Some("private"));
        assert_eq!(nm.get("feature").and_then(Value::as_str), Some("core"));

        // parent is the --mod.rs, composes -> every child + the surviving original edge
        assert_eq!(plan.parent.get("id").and_then(Value::as_str), Some("bsc-demo--widget--mod.rs"));
        assert_eq!(plan.parent.get("src").and_then(Value::as_str), Some("crates/bsc-demo/src/widget/mod.rs"));
        let composes: Vec<&str> =
            plan.parent.get("composes").and_then(Value::as_array).unwrap().iter()
                .filter_map(Value::as_str).collect();
        assert!(composes.contains(&"bsc-demo--widget--double.rs"));
        assert!(composes.contains(&"bsc-demo--widget--name-of.rs"));
        assert!(composes.contains(&"bsc-demo--widget--triple.rs"));
        assert!(composes.contains(&"bsc-demo--other.rs"), "the original non-child edge survives");

        // parent keeps the header + re-exports (matching vis) after it, and keeps the retained items
        let pc = plan.parent.get("code").and_then(Value::as_str).unwrap();
        assert!(pc.starts_with("//! Widget helpers."), "header preserved");
        assert!(pc.contains("pub use double::double;"));
        assert!(pc.contains("pub(crate) use name_of::name_of;"));
        assert!(pc.contains("pub use triple::triple;"));
        // header comes before the re-exports
        assert!(pc.find("//! Second header line.").unwrap() < pc.find("pub use double").unwrap());
        // retained items stay
        assert!(pc.contains("pub struct Widget"));
        assert!(pc.contains("const LIMIT: usize = 4;"));
        assert!(pc.contains("fn secret(n: usize)"));
        assert!(pc.contains("pub fn scaled"));
        // moved bodies are gone from the parent
        assert!(!pc.contains("pub fn double(x: usize) -> usize { x + x }"));
        assert!(!pc.contains("fn triple"));

        // consumer-only re-exports -> the allow attr is added
        let attrs: Vec<&str> = plan.parent.get("moduleAttrs").and_then(Value::as_array).unwrap()
            .iter().filter_map(Value::as_str).collect();
        assert!(attrs.contains(&"#[allow(unused_imports)]"));
    }

    /// MODULE INCEPTION IS REFUSED, not renamed. A leaf named after its own module produces `mod x`
    /// inside `mod x`, which clippy denies workspace-wide. MEASURED: 2 of 111 leaves on the backlog.
    #[test]
    fn a_leaf_named_after_its_own_module_is_refused() {
        let record = serde_json::json!({
            "id": "logs--pending.rs", "tech": "rust", "src": "crates/logs/src/pending.rs",
            "code": "pub fn pending(x: usize) -> usize { x }\npub fn other(x: usize) -> usize { x }\n",
        });
        let err = super::plan_extraction(&record, &["pending".to_string()]).expect_err("must refuse");
        assert!(err.contains("module_inception"), "{err}");
        assert!(err.contains("pending"), "it must name the function: {err}");
        // …and the sibling leaf is still extractable, so the rule costs only the clashing name.
        assert!(super::plan_extraction(&record, &["other".to_string()]).is_ok());
    }

    /// TWO TOP-LEVEL FUNCTIONS SHARING A NAME are `#[cfg]`-gated variants of one function, and both
    /// would become the SAME child record id — one silently overwriting the other. Both are dropped,
    /// not just the second: extracting half of a cfg pair is worse than extracting neither.
    #[test]
    fn a_cfg_gated_name_pair_is_not_extractable_on_either_side() {
        let code = "\
pub fn plain(x: usize) -> usize { x + x }\n\n\
#[cfg(unix)]\npub fn signal_number(x: usize) -> usize { x }\n\n\
#[cfg(windows)]\npub fn signal_number(x: usize) -> usize { x + 1 }\n";
        assert_eq!(super::extractable_leaves(code, "rust"), vec!["plain"]);
    }

    /// A BODY REACHING THROUGH `super::` IS NOT EXTRACTABLE. Moving the function one module deeper
    /// changes what `super` means, and the path silently resolves to nothing:
    /// `error[E0433]: cannot find `studio_ws` in `super``. MEASURED: 3 functions in 1 record of 39.
    #[test]
    fn a_fn_reaching_through_super_is_not_an_extractable_leaf() {
        let code = "\
pub fn plain(x: usize) -> usize { x + x }\n\n\
pub fn reaches(x: usize) -> usize { super::helper::thing(x) }\n";
        assert_eq!(super::extractable_leaves(code, "rust"), vec!["plain"]);
    }

    /// A `#[tauri::command]` FN IS NOT AN EXTRACTABLE LEAF, however pure its body reads.
    ///
    /// The macro emits `__cmd__<name>` beside the function, and `tauri::generate_handler![m::name]`
    /// resolves it in module `m` — so moving the function into a child record leaves the generated
    /// items behind. MEASURED on the method-leaf backlog: 24 such functions across 12 records were
    /// proposed, and moving them produced 60 `E0433`s in `base-studio-code`.
    ///
    /// The neighbouring plain function must still be proposed, or the rule would cost every honest leaf
    /// in a commands module.
    #[test]
    fn a_command_attributed_fn_is_not_an_extractable_leaf() {
        let code = "\
/// Pure.\npub fn double(x: usize) -> usize { x + x }\n\n\
/// A Tauri command.\n#[tauri::command]\npub fn record_attestations(x: usize) -> usize { x + 1 }\n";
        let leaves = super::extractable_leaves(code, "rust");
        assert_eq!(leaves, vec!["double"], "the command must not be proposed: {leaves:?}");
    }

    /// …and a comment between the attribute and the fn must not hide it — the walk has to scan past
    /// comments exactly as `is_test_attributed` does.
    #[test]
    fn a_comment_between_the_attribute_and_the_fn_does_not_hide_it() {
        let code = "\
#[tauri::command]\n// why this is a command\npub fn record_attestations(x: usize) -> usize { x + 1 }\n";
        assert!(super::extractable_leaves(code, "rust").is_empty(), "the attribute still applies");
    }

    /// AN INNER ATTRIBUTE IS PART OF THE PREAMBLE. `#![allow(…)]` must precede every item in its
    /// module, so inserting the re-exports above one moves it after an item and the crate stops
    /// compiling with `error: an inner attribute is not permitted in this context`.
    ///
    /// MEASURED on the extraction backlog: 1 record of 39 carried one, and it broke the workspace
    /// build — a 1-in-39 shape is exactly the kind a batch run buries.
    #[test]
    fn the_re_exports_land_after_an_inner_attribute_not_before_it() {
        let code = "//! Header.\n\n// why this is allowed\n#![allow(dead_code)]\n\npub fn double(x: usize) -> usize { x + x }\n";
        let at = super::header_end_byte(code);
        let (before, after) = code.split_at(at);
        assert!(before.contains("#![allow(dead_code)]"), "the attribute is INSIDE the preamble: {before:?}");
        assert!(after.contains("pub fn double"), "and the body follows it: {after:?}");
        assert!(
            !after.contains("#!["),
            "nothing an insertion could displace may remain after the split: {after:?}"
        );
    }

    /// A `//` comment sitting directly above the first item belongs to THAT ITEM, so the preamble must
    /// not swallow it — the re-exports would otherwise be wedged between a comment and what it explains.
    #[test]
    fn a_comment_attached_to_the_first_item_is_not_preamble() {
        let code = "//! Header.\n\n// this explains double\npub fn double(x: usize) -> usize { x + x }\n";
        let (before, after) = code.split_at(super::header_end_byte(code));
        assert!(before.trim_end().ends_with("//! Header."), "preamble stops at the header: {before:?}");
        assert!(after.starts_with("\n// this explains double"), "the comment stays with its item: {after:?}");
    }

    #[test]
    fn a_private_leaf_is_bumped_and_use_super_is_added_only_when_a_parent_name_is_referenced() {
        let plan = plan_extraction(
            &fixture(),
            &["double".into(), "name_of".into(), "triple".into()],
        )
        .unwrap();

        // self-contained pure fn: NO `use super::*`, exact body
        let d = child(&plan, "bsc-demo--widget--double.rs");
        assert_eq!(
            d.get("code").and_then(Value::as_str).unwrap(),
            "/// Double a number.\npub fn double(x: usize) -> usize { x + x }\n"
        );
        assert!(d.get("composes").and_then(Value::as_array).unwrap().is_empty());

        // references the parent's `Value` import -> `use super::*` prepended, vis kept pub(crate)
        let nm = child(&plan, "bsc-demo--widget--name-of.rs");
        let nmc = nm.get("code").and_then(Value::as_str).unwrap();
        assert!(nmc.starts_with("use super::*;\n\n"), "needs the parent import: {nmc}");
        assert!(nmc.contains("pub(crate) fn name_of"));

        // triple calls a sibling leaf -> `use super::*` + a child->child compose edge
        let t = child(&plan, "bsc-demo--widget--triple.rs");
        let tc = t.get("code").and_then(Value::as_str).unwrap();
        assert!(tc.starts_with("use super::*;\n\n"));
        let tcomp: Vec<&str> =
            t.get("composes").and_then(Value::as_array).unwrap().iter().filter_map(Value::as_str).collect();
        assert_eq!(tcomp, vec!["bsc-demo--widget--double.rs"]);
    }

    #[test]
    fn a_bare_private_fn_is_bumped_to_pub_crate() {
        // `secret` is refused (it reaches LIMIT), so prove the bump on a private leaf that is clean.
        let rec = serde_json::json!({
            "id": "bsc-demo--w.rs", "tech": "rust", "role": "algorithm", "name": "w",
            "src": "crates/bsc-demo/src/w.rs",
            "code": "//! h\nfn helper(x: u32) -> u32 { x + 1 }\npub fn other(x: u32) -> u32 { x }\n",
        });
        let plan = plan_extraction(&rec, &["helper".into()]).unwrap();
        let h = child(&plan, "bsc-demo--w--helper.rs");
        assert!(h.get("code").and_then(Value::as_str).unwrap().contains("pub(crate) fn helper"));
        // a private leaf re-exports as pub(crate)
        assert!(plan.parent.get("code").and_then(Value::as_str).unwrap()
            .contains("pub(crate) use helper::helper;"));
    }

    #[test]
    fn extract_refuses_and_says_why() {
        // IO / effectful
        let e = plan_extraction(&fixture(), &["io_write".into()]).unwrap_err();
        assert!(e.contains("std::fs") || e.contains("IO"), "reason names the impurity: {e}");

        // reaches a private parent item that stays behind
        let e = plan_extraction(&fixture(), &["scaled".into()]).unwrap_err();
        assert!(e.contains("PRIVATE") || e.contains("private"), "reason names the private coupling: {e}");

        // a private leaf that itself reaches a private const
        let e = plan_extraction(&fixture(), &["secret".into()]).unwrap_err();
        assert!(e.to_lowercase().contains("private"), "{e}");

        // a method, not a free fn
        let e = plan_extraction(&fixture(), &["bump".into()]).unwrap_err();
        assert!(e.contains("no top-level free function"), "{e}");

        // no such fn
        let e = plan_extraction(&fixture(), &["nope".into()]).unwrap_err();
        assert!(e.contains("no top-level free function"), "{e}");
    }

    /// A dir-module PARENT shaped like the real backlog: it already re-exports a child, and still holds
    /// the leaves a first decomposition wave left behind.
    fn parent_fixture() -> Value {
        let mut rec = fixture();
        rec["id"] = Value::String("bsc-demo--widget--mod.rs".into());
        rec["src"] = Value::String("crates/bsc-demo/src/widget/mod.rs".into());
        rec["folder"] = Value::String("crates/bsc-demo/src/widget".into());
        rec["composes"] = serde_json::json!(["bsc-demo--widget--already.rs"]);
        let code = rec.get("code").and_then(Value::as_str).unwrap().to_string();
        // The re-export a previous wave left, inserted after the `//!` header exactly as this transform
        // writes one.
        let code = code.replacen(
            "\nuse serde_json::Value;",
            "\npub use already::already;\n\nuse serde_json::Value;",
            1,
        );
        rec["code"] = Value::String(code);
        rec
    }

    /// #260 — A `--mod.rs` PARENT DECOMPOSES FURTHER, IN PLACE. This is the whole request: the geometry
    /// is dir -> SAME dir, so the children are SIBLINGS of the parent's existing children rather than
    /// grandchildren under a `…/widget/mod/` directory that does not exist, and the parent record is
    /// UPDATED (same id, same src, existing `composes` kept) rather than replaced by a new id.
    ///
    /// Against the code before #260 this fails at the first line: `plan_extraction` refused every
    /// `--mod.rs` id outright ("is already a `--mod.rs` dir-module, not a flat record").
    #[test]
    fn a_dir_module_parent_decomposes_in_place_into_siblings() {
        let plan = plan_extraction(&parent_fixture(), &["double".into(), "triple".into()])
            .expect("a parent decomposes further");

        assert!(plan.in_place, "the plan must know it is updating a parent, not minting one");
        // The id does not move: flat_id IS the parent id, so the store seam's remove-then-insert updates.
        assert_eq!(plan.flat_id, "bsc-demo--widget--mod.rs");
        assert_eq!(plan.parent.get("id").and_then(Value::as_str), Some("bsc-demo--widget--mod.rs"));
        assert_eq!(
            plan.parent.get("src").and_then(Value::as_str),
            Some("crates/bsc-demo/src/widget/mod.rs"),
            "the parent stays where it is"
        );
        assert_eq!(plan.parent.get("folder").and_then(Value::as_str), Some("crates/bsc-demo/src/widget"));

        // SIBLINGS, not grandchildren — the `dir` half of the geometry.
        let ids: Vec<&str> =
            plan.children.iter().filter_map(|c| c.get("id").and_then(Value::as_str)).collect();
        assert_eq!(ids, vec!["bsc-demo--widget--double.rs", "bsc-demo--widget--triple.rs"]);
        for c in &plan.children {
            let s = c.get("src").and_then(Value::as_str).unwrap();
            assert!(
                s.starts_with("crates/bsc-demo/src/widget/") && !s.contains("/mod/"),
                "a child must be a sibling in the dir the parent owns, not under `…/mod/`: {s}"
            );
            assert_eq!(c.get("folder").and_then(Value::as_str), Some("crates/bsc-demo/src/widget"));
        }

        // The parent keeps the child it already had AND gains the new ones.
        let composes: Vec<&str> = plan.parent.get("composes").and_then(Value::as_array).unwrap()
            .iter().filter_map(Value::as_str).collect();
        assert!(composes.contains(&"bsc-demo--widget--already.rs"), "an existing child edge survives: {composes:?}");
        assert!(composes.contains(&"bsc-demo--widget--double.rs"));
        assert!(composes.contains(&"bsc-demo--widget--triple.rs"));

        // The parent re-exports the new children beside the one it already re-exported, and the moved
        // bodies are gone from it.
        let pc = plan.parent.get("code").and_then(Value::as_str).unwrap();
        assert!(pc.starts_with("//! Widget helpers."), "header preserved: {pc:.40}");
        assert!(pc.contains("pub use already::already;"), "the previous wave's re-export survives");
        assert!(pc.contains("pub use double::double;"));
        assert!(pc.contains("pub use triple::triple;"));
        assert!(!pc.contains("pub fn double(x: usize) -> usize { x + x }"), "the body moved out");
        assert!(pc.contains("pub struct Widget"), "the retained items stay");
    }

    /// #260 — MODULE INCEPTION IS READ OFF THE PARENT'S OWN SEGMENT. `…/widget/mod.rs` is module
    /// `widget`, so a leaf named `widget` would land at `widget/widget.rs` — `mod widget` inside
    /// `mod widget`, which clippy denies workspace-wide.
    ///
    /// This is the guard for the one place the two geometries genuinely disagree: the flat rule reads
    /// the LAST id segment, which for a parent is the literal `mod`, so every leaf compares unequal and
    /// a real inception is planned silently. Lifting the `--mod.rs` refusal without this is a build break.
    #[test]
    fn a_leaf_named_after_its_parents_module_is_refused() {
        let rec = serde_json::json!({
            "id": "bsc-demo--widget--mod.rs", "tech": "rust", "role": "algorithm", "name": "widget",
            "src": "crates/bsc-demo/src/widget/mod.rs",
            "code": "//! h\npub fn widget(x: usize) -> usize { x }\npub fn other(x: usize) -> usize { x }\n",
        });
        let e = plan_extraction(&rec, &["widget".into()]).expect_err("inception must be refused");
        assert!(e.contains("module_inception"), "{e}");
        assert!(e.contains("widget"), "it must name the function: {e}");
        // …and the rule costs only the clashing name.
        assert!(plan_extraction(&rec, &["other".into()]).is_ok());
    }

    /// #260 lifted the `--mod.rs` refusal and MUST NOT have lifted the crate-root one: a `lib.rs` /
    /// `main.rs` is not a module, and `graph_materialize` finds the crate's root unit by that exact id.
    #[test]
    fn lifting_the_mod_rs_refusal_left_the_crate_root_one_standing() {
        for (id, src) in [
            ("bsc-demo--lib.rs", "crates/bsc-demo/src/lib.rs"),
            ("bsc-demo--main.rs", "crates/bsc-demo/src/main.rs"),
        ] {
            let mut r = fixture();
            r["id"] = Value::String(id.into());
            r["src"] = Value::String(src.into());
            let e = plan_extraction(&r, &["double".into()]).unwrap_err();
            assert!(e.contains("CRATE ROOT"), "`{id}` must still be refused: {e}");
        }
    }

    /// A CRATE ROOT is refused. Without this the verb happily plans `x--lib.rs` -> `x--lib--mod.rs`,
    /// which deletes the record `graph_materialize::Plan::select_root` finds the crate root by — the
    /// crate then builds with an empty root. The worklist proposes crate roots, so the verb must refuse.
    #[test]
    fn extract_refuses_a_crate_root() {
        let mut lib = fixture();
        lib["id"] = Value::String("bsc-demo--lib.rs".into());
        lib["src"] = Value::String("crates/bsc-demo/src/lib.rs".into());
        let e = plan_extraction(&lib, &["double".into()]).unwrap_err();
        assert!(e.contains("CRATE ROOT"), "{e}");

        let mut main = fixture();
        main["id"] = Value::String("bsc-demo--main.rs".into());
        main["src"] = Value::String("crates/bsc-demo/src/main.rs".into());
        let e = plan_extraction(&main, &["double".into()]).unwrap_err();
        assert!(e.contains("CRATE ROOT"), "{e}");
    }

    /// A `#[cfg]`-GATED FUNCTION IS NOT EXTRACTABLE, at either seam — not even a lone one. The parent's
    /// re-export is unconditional while the item is not, so on a target where the gate is false the
    /// child module is empty and `pub use x::x;` names something that is not there.
    ///
    /// MEASURED, and only by the compiler: `#[cfg(windows)] bash_in_roots` gave `E0432 no bash_in_roots
    /// in platform::shell::bash_in_roots / found an item that was configured out`, and
    /// `#[cfg(windows)] read_stream` gave `E0603 module import read_stream is private`. Both were
    /// extracted on Linux, where the gate is false.
    #[test]
    fn a_lone_cfg_gated_fn_is_not_extractable_either() {
        let code = "//! S.\n\n\
/// Windows only.\n#[cfg(windows)]\npub fn bash_in_roots(x: usize) -> usize { x + 1 }\n\n\
pub fn plain(x: usize) -> usize { x + 2 }\n";
        // the classifier stops proposing it …
        assert_eq!(super::extractable_leaves(code, "rust"), vec!["plain"]);
        // … and the verb refuses it by name.
        let rec = serde_json::json!({
            "id": "bsc-demo--shell--mod.rs", "tech": "rust", "role": "algorithm", "name": "shell",
            "src": "crates/bsc-demo/src/shell/mod.rs", "composes": [], "code": code,
        });
        let e = plan_extraction(&rec, &["bash_in_roots".into()]).expect_err("a gated fn must be refused");
        assert!(e.contains("`#[cfg]`-gated"), "{e}");
        assert!(plan_extraction(&rec, &["plain".into()]).is_ok(), "the rule costs only the gated fn");
    }

    /// A PARENT GLOB CANNOT BE ENUMERATED, so every child takes `use super::*`. `use crate::prelude::*`
    /// binds names this transform cannot see; a child reaching one of them looked self-contained and was
    /// emitted without the import. MEASURED: `mcp_install_dir` and `cache_dir` both reach `bsc_base_dir`
    /// through their parent's prelude glob — `error[E0425]: cannot find function `bsc_base_dir``.
    ///
    /// The child also carries `#[allow(unused_imports)]`, because a glob is an over-approximation by
    /// construction and an unused import is a red gate here.
    #[test]
    fn a_parent_glob_gives_every_child_use_super() {
        let rec = serde_json::json!({
            "id": "bsc-demo--mcp--mod.rs", "tech": "rust", "role": "algorithm", "name": "mcp",
            "src": "crates/bsc-demo/src/mcp/mod.rs", "composes": [],
            "code": "//! M.\n\nuse crate::prelude::*;\n\n\
pub fn install_dir(n: &str) -> String { base_dir(n) }\n\n\
pub fn plain(x: usize) -> usize { x + 1 }\n",
        });
        let plan = plan_extraction(&rec, &["install_dir".into(), "plain".into()]).unwrap();
        for c in &plan.children {
            let code = c.get("code").and_then(Value::as_str).unwrap();
            assert!(code.starts_with("use super::*;"),
                "a glob in the parent is unenumerable, so every child takes it: {code}");
            let attrs: Vec<&str> = c.get("moduleAttrs").and_then(Value::as_array).unwrap()
                .iter().filter_map(Value::as_str).collect();
            assert!(attrs.contains(&"#[allow(unused_imports)]"),
                "a glob is an over-approximation, so an unused one must not redden the gate: {attrs:?}");
        }
    }

    /// THE PARENT ALLOWS AN UNUSED IMPORT ONCE A FUNCTION LEAVES, even when every re-export is used in
    /// the retained body. The moved function may have been the ONLY reader of one of the parent's `use`
    /// declarations. MEASURED: `src-tauri--project--graph-layout--mod.rs` kept `use crate::prelude::*;`
    /// after `cache_dir` and `header` left, and `-D warnings` makes that a red gate.
    #[test]
    fn the_parent_allows_an_unused_import_even_when_every_reexport_is_used() {
        let rec = serde_json::json!({
            "id": "bsc-demo--layout--mod.rs", "tech": "rust", "role": "algorithm", "name": "layout",
            "src": "crates/bsc-demo/src/layout/mod.rs", "composes": [],
            "code": "//! L.\n\nuse std::path::PathBuf;\n\n\
pub fn cache_dir() -> PathBuf { PathBuf::new() }\n\n\
pub fn top() -> PathBuf { cache_dir() }\n",
        });
        let plan = plan_extraction(&rec, &["cache_dir".into()]).unwrap();
        // `cache_dir` IS referenced by the retained `top`, so the old consumer-only rule added nothing.
        let pc = plan.parent.get("code").and_then(Value::as_str).unwrap();
        assert!(pc.contains("cache_dir()"), "the re-export is used in the retained body: {pc}");
        let attrs: Vec<&str> = plan.parent.get("moduleAttrs").and_then(Value::as_array).unwrap()
            .iter().filter_map(Value::as_str).collect();
        assert!(attrs.contains(&"#[allow(unused_imports)]"),
                "the moved fn may have been an import's only reader: {attrs:?}");
    }

    /// A `#[tauri::command]` DECLARED AS A FACET is refused, at BOTH seams. The attribute moved out of
    /// the body into `tauriCommands` (`a-tauri-command-is-a-record-facet`), which made the
    /// [`ITEM_GENERATING_ATTRS`] text scan — the guard that exists for exactly this — blind to it.
    ///
    /// MEASURED: `src-tauri--extensions--mcp--mod.rs` carries four entries; a wave extracted two and the
    /// build failed in `graph-materialize` with "the facet names a function that is not there". Only the
    /// compiler caught it, three minutes into a workspace check.
    #[test]
    fn a_tauri_command_declared_as_a_facet_is_refused() {
        let code = "//! M.\n\n\
pub fn mcp_status(name: &str) -> usize { name.len() }\n\n\
pub fn plain(x: usize) -> usize { x + 1 }\n";
        let rec = serde_json::json!({
            "id": "src-tauri--extensions--mcp--mod.rs", "tech": "rust", "role": "algorithm", "name": "mcp",
            "src": "src-tauri/src/extensions/mcp/mod.rs", "composes": [], "code": code,
            "tauriCommands": [{ "name": "mcp_status" }],
        });
        // The BODY carries no attribute, so the text scan sees a plain pure leaf …
        assert!(super::extractable_leaves(code, "rust").contains(&"mcp_status".to_string()));
        // … and only the facet says otherwise. The verb refuses it.
        let e = plan_extraction(&rec, &["mcp_status".into()]).expect_err("a command must be refused");
        assert!(e.contains("tauriCommands"), "{e}");
        assert!(plan_extraction(&rec, &["plain".into()]).is_ok(), "the rule costs only the command");
        // … and the WORKLIST stops proposing it, so the record is not a two-leaf finding at all.
        assert!(super::worklist(std::slice::from_ref(&rec)).is_empty(),
                "one leaf remains once the command is subtracted: {:?}", super::worklist(std::slice::from_ref(&rec)));
    }

    /// A NAME THAT OCCURS ONLY INSIDE A STRING LITERAL IS NOT A REFERENCE. The child would otherwise be
    /// handed a `use super::*` it does not use, and this workspace gates on
    /// `clippy --all-targets -- -D warnings`, so that is a RED GATE rather than a harmless extra import.
    /// MEASURED: `bsc-sound--release--artifact-name.rs` returns the literal `"kit.json"` and the parent
    /// has a `kit` in scope.
    ///
    /// The inline-capture case is the reason the rule is not simply "blank every literal": a `{` in the
    /// literal keeps it whole, because `format!("{helper}")` IS a reference and losing it drops an import
    /// the child needs — a compile error, against a warning in the other direction.
    #[test]
    fn a_name_only_inside_a_string_literal_does_not_earn_a_use_super() {
        let rec = serde_json::json!({
            "id": "bsc-demo--release--mod.rs", "tech": "rust", "role": "algorithm", "name": "release",
            "src": "crates/bsc-demo/src/release/mod.rs", "composes": [],
            "code": "//! R.\n\nuse crate::kit;\n\n\
pub fn artifact_name(_k: &str) -> &'static str { \"kit.json\" }\n\n\
pub fn labelled() -> String { format!(\"{kit}\") }\n\n\
pub fn other(x: usize) -> usize { x }\n",
        });
        let plan = plan_extraction(&rec, &["artifact_name".into(), "labelled".into()]).unwrap();
        let code = |id: &str| -> String {
            plan.children.iter().find(|c| c.get("id").and_then(Value::as_str) == Some(id))
                .unwrap().get("code").and_then(Value::as_str).unwrap().to_string()
        };
        assert!(
            !code("bsc-demo--release--artifact-name.rs").contains("use super::*"),
            "`kit` appears only inside \"kit.json\" — that is not a reference: {}",
            code("bsc-demo--release--artifact-name.rs")
        );
        assert!(
            code("bsc-demo--release--labelled.rs").starts_with("use super::*;"),
            "an INLINE CAPTURE is a real reference and must keep the import: {}",
            code("bsc-demo--release--labelled.rs")
        );
    }

    /// A `#[cfg]`-GATED PAIR WHOSE HALVES DIFFER IN PURITY. The classifier's pair census used to run
    /// over the names that had already PASSED the leaf filter, so an impure `#[cfg(windows)]` half was
    /// gone by the time the census ran and the pure half looked like a lone function. MEASURED:
    /// `bsc-fleet--ledger--mod.rs` proposed both `os_alive` and `tree_kill` on exactly that hole.
    ///
    /// Taking half of a pair breaks only the platform whose variant stayed behind — Windows, which
    /// nothing on this machine compiles — so the damage would have shipped unobserved. BOTH seams are
    /// pinned here: the classifier must stop proposing it, and the verb must refuse it when a human
    /// names it anyway.
    #[test]
    fn a_cfg_pair_with_one_impure_half_is_dropped_by_the_classifier_and_refused_by_the_verb() {
        let code = "//! L.\n\n\
#[cfg(windows)]\npub fn os_alive(pid: u32) -> bool { std::process::id() == pid }\n\n\
#[cfg(not(windows))]\npub fn os_alive(pid: u32) -> bool { pid > 0 }\n\n\
pub fn plain(x: usize) -> usize { x + 1 }\n";
        // The classifier drops BOTH halves and keeps the honest neighbour.
        assert_eq!(super::extractable_leaves(code, "rust"), vec!["plain"]);

        let rec = serde_json::json!({
            "id": "bsc-demo--ledger--mod.rs", "tech": "rust", "role": "algorithm", "name": "ledger",
            "src": "crates/bsc-demo/src/ledger/mod.rs", "composes": [], "code": code,
        });
        let e = plan_extraction(&rec, &["os_alive".into()]).expect_err("the verb must refuse a pair");
        assert!(e.contains("`#[cfg]`-gated variants"), "{e}");
        assert!(e.contains("2 top-level functions"), "it must say how many: {e}");
        // The rule costs only the pair.
        assert!(plan_extraction(&rec, &["plain".into()]).is_ok());
    }

    /// The connection split, at the VERB: a store reader extracts, an opener is refused by name.
    #[test]
    fn extract_takes_a_connection_reader_and_refuses_an_opener() {
        let code = "//! Store.\n\nuse rusqlite::Connection;\n\n\
/// Count.\npub fn count(conn: &Connection, t: &str) -> i64 { conn.query_row(t) }\n\n\
/// Open.\npub fn open_db(p: &str) -> Connection { Connection::open(p).unwrap() }\n";
        let rec = serde_json::json!({
            "id": "bsc-demo--store.rs", "tech": "rust", "role": "algorithm", "name": "store",
            "src": "crates/bsc-demo/src/store.rs", "composes": [], "code": code,
        });
        let plan = plan_extraction(&rec, &["count".into()]).expect("a store reader extracts cleanly");
        assert_eq!(plan.children.len(), 1);
        let e = plan_extraction(&rec, &["open_db".into()]).unwrap_err();
        assert!(e.contains("OWNS a connection"), "{e}");
    }
}
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::{Path, PathBuf};

    fn repo() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().parent().unwrap().to_path_buf()
    }

    fn rec(id: &str, role: &str, tech: &str, code: &str) -> Value {
        serde_json::json!({ "id": id, "role": role, "tech": tech, "code": code })
    }

    #[test]
    fn a_pure_formatter_and_predicate_are_extractable_leaves() {
        let code = "\
pub fn peak_line(mb: f64) -> String { format!(\"{mb:.1} MB\") }
pub fn is_frame_line(s: &str) -> bool { s.starts_with('#') && s.len() > 1 }
";
        assert_eq!(extractable_leaves(code, "rust"), vec!["peak_line", "is_frame_line"]);
    }

    #[test]
    fn a_stateful_or_io_function_is_not_a_leaf() {
        // reads a global Mutex — not pure
        let stateful = "pub fn get() -> u32 { *STATE.lock().unwrap() }";
        assert!(extractable_leaves(stateful, "rust").is_empty());
        // does IO
        let io = "pub fn dump(p: &Path) { std::fs::write(p, \"x\").ok(); }";
        assert!(extractable_leaves(io, "rust").is_empty());
        // async
        let a = "pub async fn fetch() -> u32 { 1 }";
        assert!(extractable_leaves(a, "rust").is_empty());
    }

    #[test]
    fn inline_test_fns_and_impl_methods_do_not_count() {
        let code = "\
pub fn only_real_leaf(x: u32) -> u32 { x + 1 }
struct S;
impl S { pub fn method(&self) -> u32 { 1 } }
#[cfg(test)]
mod tests { #[test] fn t() { assert_eq!(1, 1); } }
";
        // the impl method is under impl_item, the test fn under mod_item — neither is top-level.
        assert_eq!(extractable_leaves(code, "rust"), vec!["only_real_leaf"]);
    }

    /// A store HANDLE is not the function's impurity. `Connection` used to be a blunt [`IMPURE_MARKERS`]
    /// substring, which excluded 90 functions across 17 records that merely receive a handle — and hit
    /// four things that were not connections at all.
    #[test]
    fn a_function_handed_a_connection_is_a_leaf_and_one_that_owns_it_is_not() {
        // RECEIVES the handle — a pure function OF the store.
        let takes = "pub fn domains(conn: &Connection, k: &str) -> usize { conn.query_row(k).len() }";
        assert_eq!(extractable_leaves(takes, "rust"), vec!["domains"]);
        // OPENS one.
        let opens = "pub fn db() -> Connection { Connection::open_in_memory().unwrap() }";
        assert!(extractable_leaves(opens, "rust").is_empty(), "an opener is not a leaf");
        // HANDS ONE BACK — the ownership is in the return type, not the body.
        let back = "pub fn dup(p: &str) -> rusqlite::Result<Connection> { mk(p) }";
        assert!(extractable_leaves(back, "rust").is_empty(), "a fn returning a handle is not a leaf");
        // BINDS one in the body.
        let binds = "pub fn n(p: &str) -> usize { let c: Connection = mk(p); c.rows() }";
        assert!(extractable_leaves(binds, "rust").is_empty(), "a fn binding a handle is not a leaf");
        // NOT a connection at all — whole-identifier matching, which the substring test failed.
        let kind = "pub fn is_refused(e: &ErrorKind) -> bool { matches!(e, ErrorKind::ConnectionRefused) }";
        assert_eq!(extractable_leaves(kind, "rust"), vec!["is_refused"]);
    }

    /// A FUNCTION-LOCAL memo `static` is not shared state. `OnceLock` is an [`IMPURE_MARKERS`] token, and
    /// the scan is a substring test over the function's own text, so the memo idiom — write at most once
    /// through `get_or_init`, only ever read back — disqualified a referentially transparent function.
    /// MEASURED: 137 of the repo's 164 `static` declarations are function-local, and ~63 of the 88
    /// functions a state marker blocked are this shape.
    #[test]
    fn a_function_local_memo_static_is_not_shared_state() {
        let memo = "pub fn declared(t: &str) -> usize {\n    \
static RE: OnceLock<regex::Regex> = OnceLock::new();\n    \
let re = RE.get_or_init(|| regex::Regex::new(\"x\").expect(\"declared\"));\n    \
re.find_iter(t).count()\n}";
        assert_eq!(extractable_leaves(memo, "rust"), vec!["declared"]);

        // path-qualified, and the memo IS the return value
        let qualified = "pub fn pat() -> &'static regex::Regex {\n    \
static RE: std::sync::OnceLock<regex::Regex> = std::sync::OnceLock::new();\n    \
RE.get_or_init(|| regex::Regex::new(\"y\").unwrap())\n}";
        assert_eq!(extractable_leaves(qualified, "rust"), vec!["pat"]);

        // WRITTEN — `set` is not a compute-or-return read, so the cell is shared state again.
        let written = "pub fn arm(v: u32) -> bool {\n    \
static CELL: OnceLock<u32> = OnceLock::new();\n    CELL.set(v).is_ok()\n}";
        assert!(extractable_leaves(written, "rust").is_empty(), "a written cell is not a memo");

        // not a memo CELL, however it is read.
        let guarded = "pub fn n() -> usize {\n    \
static M: Mutex<usize> = Mutex::new(0);\n    *M.get_or_init(|| 1)\n}";
        assert!(extractable_leaves(guarded, "rust").is_empty(), "a Mutex is not a memo cell");

        // `static mut` is shared mutable state by definition.
        let muta = "pub fn n() -> usize {\n    static mut C: usize = 0;\n    unsafe { C }\n}";
        assert!(extractable_leaves(muta, "rust").is_empty(), "`static mut` is never a memo");

        // A LET binding of a cell is not a `static` declaration — only `static_item` is masked, which is
        // what makes the rule a SCOPE rule rather than a type-name rule.
        let bound = "pub fn n() -> usize {\n    \
let c: OnceLock<usize> = OnceLock::new();\n    *c.get_or_init(|| 1)\n}";
        assert!(extractable_leaves(bound, "rust").is_empty(), "a local binding is not a memo static");

        // Only the DECLARATION is masked: a memo whose initialiser does IO is still IO.
        let io = "pub fn seed() -> String {\n    \
static S: OnceLock<String> = OnceLock::new();\n    \
S.get_or_init(|| std::fs::read_to_string(\"p\").unwrap_or_default()).clone()\n}";
        assert!(extractable_leaves(io, "rust").is_empty(), "a memo of an IO read is still IO");
    }

    /// A `--mod.rs` DIR-MODULE PARENT is a worklist candidate. Excluding it by id was the one rule that
    /// guaranteed whatever did not extract in a decomposition wave was never counted again.
    #[test]
    fn a_mod_rs_dir_module_parent_is_on_the_worklist() {
        let code = "\
pub use double::double;

pub fn peak_line(mb: f64) -> String { format!(\"{mb:.1} MB\") }
pub fn is_frame_line(s: &str) -> bool { s.starts_with('#') && s.len() > 1 }
";
        let impls = vec![rec("bsc-x--report--mod.rs", "algorithm", "rust", code)];
        let w = worklist(&impls);
        assert_eq!(w.len(), 1, "a dir-module parent's remainder is a finding");
        assert_eq!(w[0].names, vec!["peak_line", "is_frame_line"]);
    }

    #[test]
    fn a_decomposed_single_leaf_record_is_not_on_the_worklist() {
        // what an already-split observability leaf looks like: exactly one pure fn.
        let impls = vec![rec(
            "src-tauri--observability--renderer-watch--peak-line.rs",
            "algorithm",
            "rust",
            "pub fn peak_line(mb: f64) -> String { format!(\"{mb:.1}\") }",
        )];
        // classifier sees it as one extractable leaf ...
        assert_eq!(extractable_leaves(impls[0].get("code").unwrap().as_str().unwrap(), "rust").len(), 1);
        // ... so it is NOT a multi-method finding.
        assert!(worklist(&impls).is_empty());
    }

    /// A COMMAND SURFACE IS JUDGED BY ITS CODE, not by its id. This test asserted the opposite until
    /// `is_candidate_record` dropped its three id filters: a `--cli.rs` / `--nouns.rs` record used to be
    /// excluded by NAME, which meant the largest records in the repo (`bsc-component--cli.rs`, 718 KB /
    /// 130 fns) were the ones nothing measured. Cohesion is `cohesion_reason`'s call, from the code.
    #[test]
    fn a_command_surface_is_judged_by_its_code_not_its_id() {
        let code = "\
pub fn fmt_a(x: u32) -> String { format!(\"{x}\") }
pub fn fmt_b(y: u32) -> String { format!(\"{y}\") }
";
        for id in ["bsc-graph--cli.rs", "bsc-graph--nouns.rs", "bsc-graph--fmt--mod.rs", "bsc-graph--fmt.rs"] {
            let impls = vec![rec(id, "algorithm", "rust", code)];
            assert_eq!(worklist(&impls).len(), 1, "`{id}` holds two independent formatters — a finding");
        }
        // The role gate is the one filter left, and it still holds.
        let doc = vec![rec("bsc-graph--cli.rs", "doc", "rust", code)];
        assert!(worklist(&doc).is_empty(), "a doc record is never a decomposition target");
    }

    #[test]
    fn a_json_parsing_collection_stays_genuine() {
        // uses serde_json but each leaf is an INDEPENDENT reader — patterns/closure/backing shape. A
        // serde fraction was tried and rejected precisely because it demotes collections like this.
        let code = "\
pub fn name_of(v: &Value) -> String { v.get(\"n\").and_then(|x| x.as_str()).unwrap_or(\"\").to_string() }
pub fn kind_of(v: &Value) -> String { v.get(\"k\").and_then(|x| x.as_str()).unwrap_or(\"\").to_string() }
pub fn count_of(v: &Value) -> usize { v.as_array().map(|a| a.len()).unwrap_or(0) }
";
        let impls = vec![rec("bsc-x--patterns.rs", "algorithm", "rust", code)];
        assert_eq!(worklist(&impls).len(), 1, "independent JSON readers are a genuine collection");
        assert!(demoted(&impls).is_empty());
    }

    #[test]
    fn a_std_only_grammar_collection_stays_genuine() {
        // node_urn / motion shape: independent std-only string helpers — a genuine collection worth
        // splitting, EVEN THOUGH they may call each other (inter-leaf calls are not a cohesion signal).
        let code = "\
pub fn is_urn(s: &str) -> bool { s.starts_with('@') }
pub fn parse_urn(s: &str) -> String { s.trim_start_matches('@').to_string() }
pub fn format_urn(name: &str) -> String { format!(\"@{name}\") }
";
        let impls = vec![rec("bsc-x--node-urn.rs", "algorithm", "rust", code)];
        assert_eq!(worklist(&impls).len(), 1, "std-only grammar helpers are a genuine collection");
        assert!(demoted(&impls).is_empty());
    }

    #[test]
    fn a_type_coupled_module_is_demoted() {
        // most leaf SIGNATURES name the module's own struct — methods-in-disguise over its data.
        let code = "\
pub struct Facet { pub k: String }
pub fn from_a(f: Facet) -> Facet { f }
pub fn from_b(f: &Facet) -> String { f.k.clone() }
pub fn tag(name: &str) -> Facet { Facet { k: name.to_string() } }
";
        let impls = vec![rec("bsc-x--build-facet.rs", "algorithm", "rust", code)];
        assert!(worklist(&impls).is_empty(), "a type-coupled module is demoted");
        assert!(demoted(&impls)[0].1.contains("type-coupled"));
    }

    #[test]
    fn a_private_coupled_module_is_demoted() {
        // leaves that lean on a PRIVATE parent helper (which stays in the parent) are entangled — the
        // exports/usage/similarity shape. `shared` is private + impure, so it is NOT itself a leaf; the
        // pure leaves `a`/`b` that call it would each need an explicit `use super::shared`.
        let code = "\
fn shared(p: &str) -> String { std::fs::read_to_string(p).unwrap_or_default() }
pub fn a(p: &str) -> usize { shared(p).len() }
pub fn b(p: &str) -> bool { shared(p).is_empty() }
pub fn plain(x: u32) -> u32 { x + 1 }
";
        let impls = vec![rec("bsc-x--exports.rs", "algorithm", "rust", code)];
        assert!(worklist(&impls).is_empty(), "private-coupled leaves are demoted");
        assert!(
            demoted(&impls)[0].1.contains("private-coupled"),
            "reason: {}",
            demoted(&impls)[0].1
        );
    }

    #[test]
    fn drift_flags_a_new_record_and_a_grown_one_but_not_the_backlog() {
        let mut baseline = BTreeMap::new();
        baseline.insert("old.rs".to_string(), 3usize);
        let mut current = BTreeMap::new();
        current.insert("old.rs".to_string(), 3); // unchanged — fine
        current.insert("new.rs".to_string(), 2); // NEW — violation
        let v = drift_against(&current, &baseline);
        assert_eq!(v.len(), 1);
        assert!(v[0].contains("new.rs"));
        // now grow the baselined one
        current.insert("old.rs".to_string(), 4);
        let v2 = drift_against(&current, &baseline);
        assert!(v2.iter().any(|s| s.contains("old.rs") && s.contains("3 -> 4")));
    }

    // ---- the DRIFT GATE, over the real committed repo store ----

    fn baseline_path() -> PathBuf {
        repo().join("graph/method-leaf-baseline.json")
    }

    fn read_store_counts() -> BTreeMap<String, usize> {
        // Through the MERGED loader — the drift gate counts records, and counting only the ones still
        // in the store FILE would silently shrink its population as records split out into
        // `graph/records/` (`epic-retire-json-ledgers-for-db-and-git-drivers`).
        let store = crate::repo_store::read_at(&repo().join("graph/algorithms.json"))
            .expect("repo store readable")
            .expect("repo store exists");
        let impls = store.get("implementations").and_then(Value::as_array).cloned().unwrap_or_default();
        counts(&impls)
    }

    fn read_baseline() -> BTreeMap<String, usize> {
        let raw = std::fs::read_to_string(baseline_path()).expect("method-leaf-baseline.json exists (regenerate with the ignored writer test)");
        serde_json::from_str(&raw).expect("baseline parses")
    }

    /// Regenerate the baseline from the current committed store:
    ///   cargo nextest run -p bsc-graph --run-ignored ignored-only -E 'test(write_method_leaf_baseline)'
    /// (or `cargo test -p bsc-graph -- --ignored write_method_leaf_baseline`). Commit the result. Do this
    /// deliberately, when a legitimately-cohesive multi-leaf record lands or the backlog is decomposed.
    #[test]
    #[ignore = "generator: writes graph/method-leaf-baseline.json from the current store"]
    fn write_method_leaf_baseline() {
        let current = read_store_counts();
        let json = serde_json::to_string_pretty(&current).unwrap();
        std::fs::write(baseline_path(), format!("{json}\n")).expect("write baseline");
        eprintln!("wrote {} baselined records to {:?}", current.len(), baseline_path());
    }

    /// THE GATE: no record may exceed its baseline, and no NEW record may appear with >1 extractable leaf.
    /// The backlog is grandfathered by the committed baseline; this only catches DRIFT.
    #[test]
    fn no_record_grows_new_extractable_method_leaves() {
        let violations = drift_against(&read_store_counts(), &read_baseline());
        assert!(
            violations.is_empty(),
            "multi-method drift ({} record(s)) — decompose them, or if genuinely cohesive regenerate the \
             baseline (see write_method_leaf_baseline):\n  {}",
            violations.len(),
            violations.join("\n  ")
        );
    }
}
